import{_ as c,C as r,o as n,c as h,j as d,a as e,E as o,a5 as i}from"./chunks/framework.BYIUCCsM.js";const z=JSON.parse('{"title":"虚拟滚动","description":"","frontmatter":{},"headers":[],"relativePath":"components/virtualizer.md","filePath":"components/virtualizer.md","lastUpdated":1787353937000}'),s={name:"components/virtualizer.md"},u={id:"虚拟滚动",tabindex:"-1"};function b(p,t,m,x,g,q){const l=r("Badge"),a=r("XhDemo");return n(),h("div",null,[d("h1",u,[t[0]||(t[0]=e("虚拟滚动 ",-1)),o(l,{type:"info",text:"virtualizer"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#虚拟滚动","aria-label":'Permalink to "虚拟滚动 <Badge type="info" text="virtualizer" />"'},"​",-1))]),t[3]||(t[3]=i('<p>只渲染窗口内的条目，列表再长也只画那几十个。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>条目上千甚至上万。</li><li>首屏卡顿的根源是 DOM 节点太多。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>条目只有几十上百条：虚拟化带来的复杂度不值得。</li><li>需要浏览器的页内查找命中所有条目：没渲染的条目搜不到。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>支持动态高度（量出来而不是猜）、横向列表与多列。</li><li><code>overscan</code> 决定窗口外多渲几个，滚动时不露白。</li><li>可以滚到指定条目。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一万条只渲可视区那几条，root 要有确定高度，条目的主轴尺寸由作者按 estimateSize 自己写</p>',10)),o(a,{src:"virtualizer/01-basic"}),t[4]||(t[4]=d("h3",{id:"动态高度",tabindex:"-1"},[e("动态高度 "),d("a",{class:"header-anchor",href:"#动态高度","aria-label":'Permalink to "动态高度"'},"​")],-1)),t[5]||(t[5]=d("p",null,"条目开了 measure 就把真实尺寸回喂给内核，estimateSize 只是首帧的起点，滚过一遍就收敛",-1)),o(a,{src:"virtualizer/02-dynamic"}),t[6]||(t[6]=d("h3",{id:"滚到指定条目",tabindex:"-1"},[e("滚到指定条目 "),d("a",{class:"header-anchor",href:"#滚到指定条目","aria-label":'Permalink to "滚到指定条目"'},"​")],-1)),t[7]||(t[7]=d("p",null,"scrollToIndex 按 align 落位：start 贴上沿、center 居中、end 贴下沿，越界下标由内核夹住",-1)),o(a,{src:"virtualizer/03-scroll-to"}),t[8]||(t[8]=d("h3",{id:"横向列表",tabindex:"-1"},[e("横向列表 "),d("a",{class:"header-anchor",href:"#横向列表","aria-label":'Permalink to "横向列表"'},"​")],-1)),t[9]||(t[9]=d("p",null,"horizontal 把主轴换成行内轴：位移改写进行首侧，条目宽度由作者写，gap 由内核直接算进位移",-1)),o(a,{src:"virtualizer/04-horizontal"}),t[10]||(t[10]=d("h3",{id:"挂自绘滚动条",tabindex:"-1"},[e("挂自绘滚动条 "),d("a",{class:"header-anchor",href:"#挂自绘滚动条","aria-label":'Permalink to "挂自绘滚动条"'},"​")],-1)),t[11]||(t[11]=d("p",null,"滚动容器是视口，给它一个 id 交给滚动条即可；虚拟滚动只管渲哪几条，滚动条只管画滚动位置",-1)),o(a,{src:"virtualizer/05-scrollbar"}),t[12]||(t[12]=i('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-virtualizer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhVirtualizerContent</code> <code>XhVirtualizerItem</code> <code>XhVirtualizerRoot</code> <code>XhVirtualizerViewport</code></td></tr><tr><td>组合式函数</td><td><code>useVirtualizer</code></td></tr><tr><td>状态机</td><td><code>virtualizerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/virtualizer.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;virtualizer&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>item</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>总条数，默认 0。</td></tr><tr><td><code>estimateSize</code></td><td><code>number | ((index: number) =&gt; number)</code></td><td></td><td>每条的估算主轴尺寸（px）。等高列表可以直接给一个数字。 不给按 0 算：所有条目都会落进窗口，先渲出来再靠 measureElement 回喂真实尺寸。</td></tr><tr><td><code>overscan</code></td><td><code>number</code></td><td></td><td>可视区前后各多渲几条，默认 5。</td></tr><tr><td><code>horizontal</code></td><td><code>boolean</code></td><td></td><td>横向列表（主轴是行内轴），默认 false。</td></tr><tr><td><code>gap</code></td><td><code>number</code></td><td></td><td>相邻两条之间的主轴间距（px），默认 0。位移由内核直接算进去，不靠外边距。</td></tr><tr><td><code>getItemKey</code></td><td><code>(index: number) =&gt; string | number</code></td><td></td><td>条目身份。默认即下标；列表会增删时给稳定 key，测量缓存才跟得住条目。</td></tr><tr><td><code>onChange</code></td><td><code>(details: VirtualizerChangeDetails) =&gt; void</code></td><td></td><td>该渲什么变了。只在快照真的变了时回调，滚动但可见区间没变不会触发。</td></tr><tr><td><code>scrollMargin</code></td><td><code>number</code></td><td></td><td>列表起点距滚动容器起点的距离（px），默认 0。 列表上方还有别的内容（页头、筛选栏）时给它，否则区间会整体偏掉那一截。</td></tr><tr><td><code>paddingStart</code></td><td><code>number</code></td><td></td><td>列表前后的内边距（px），默认 0。计进总长，第一条从 paddingStart 处起算。</td></tr><tr><td><code>paddingEnd</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>lanes</code></td><td><code>number</code></td><td></td><td>多列网格的列数，默认 1（单列）。条目按下标轮流落到各道上。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>change</code></td><td><code>VirtualizerChangeDetails</code></td><td>该渲什么变了；detail 为 <code>{ virtualItems, totalSize, startIndex, endIndex }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhVirtualizerRoot</code></td><td><code>default</code></td><td><code>VirtualizerRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>scrolling</code></p><p><strong>事件</strong>：<code>SCROLL.START</code> · <code>SCROLL.END</code> · <code>MEASURE</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useVirtualizer</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>virtualItems</code></td><td><code>readonly VirtualizerItemState[]</code></td><td>此刻该渲染哪些下标，以及它们的位移与尺寸。</td></tr><tr><td><code>totalSize</code></td><td><code>number</code></td><td>整份列表的主轴总长（px）。</td></tr><tr><td><code>startIndex</code></td><td><code>number | null</code></td><td>可视区首条下标（不含过扫描）；一条都排不下时为 null。</td></tr><tr><td><code>endIndex</code></td><td><code>number | null</code></td><td>可视区末条下标（不含过扫描）；一条都排不下时为 null。</td></tr><tr><td><code>horizontal</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>lanes</code></td><td><code>number</code></td><td></td></tr><tr><td><code>scrolling</code></td><td><code>boolean</code></td><td>手正在滚。</td></tr><tr><td><code>scrollToIndex</code></td><td><code>(index: number, options?: VirtualizerScrollToOptions) =&gt; void</code></td><td>滚到第几条。越界下标由内核夹住。</td></tr><tr><td><code>measureElement</code></td><td><code>(element: HTMLElement | null) =&gt; void</code></td><td>把条目节点的真实尺寸回喂给内核（动态高度用）。传 null 无副作用。</td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>丢掉全部实测尺寸重新按估算值排。视口换了一种排版时用得上。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: VirtualizerItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/virtualizer.css</code> 按部件选择：<code>[data-scope=&quot;virtualizer&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>root</code></td><td><code>data-scrolling</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>content</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>item</code></td><td><code>data-index</code></td><td>props.index</td></tr><tr><td><code>item</code></td><td><code>data-lane</code></td><td>item.lane | undefined</td></tr><tr><td><code>item</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr></tbody></table><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./list">列表</a>、<a href="./table">表格</a>、<a href="./select">选择器</a>的长选项列表、<a href="./transfer">穿梭框</a>配合。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>条目高度差异大时用动态高度模式，别用估值硬撑。</li><li>提供&quot;滚到某条&quot;的入口，否则用户永远找不回刚才看的位置。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>在虚拟列表里放高度会突变的内容（图片没预留宽高比），滚动时位置乱跳。</li><li>依赖 Ctrl + F 查找。</li></ul>',36))])}const P=c(s,[["render",b]]);export{z as __pageData,P as default};
